import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { PDFDownloadLink, Document, Page, Text, View, StyleSheet, Image } from '@react-pdf/renderer';
import '../css/GST.css';

// Company Information
const companyInfo = {
  name: 'E I O Digital Solutions',
  legalName: 'Private Limited',
  address: '1A/1-G9 Wavoo Centre, Madurai Road, Tirunelveli-627001',
  contact: 'Phone: +91 9840624407, +91 9444224407',
  email: 'Email: myeiokln@gmail.com',
  website: 'Website: https.myeio.in',
  gstin: 'GSTIN: 32AAAFQ1234A1Z5'
};

// PDF Styles for GST Report
const gstPdfStyles = StyleSheet.create({
  page: {
    padding: 25,
    fontSize: 9,
    fontFamily: 'Helvetica',
    lineHeight: 1.3
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 12,
    alignItems: 'flex-start'
  },
  logoContainer: {
    width: '30%',
    alignItems: 'center'
  },
  logo: {
    width: 70,
    height: 70,
    marginBottom: 5
  },
  companyName: {
    fontSize: 10,
    fontWeight: 'bold',
    color: '#2c3e50',
    textAlign: 'center'
  },
  companyInfo: {
    width: '65%',
    textAlign: 'right'
  },
  companyNameMain: {
    fontSize: 12,
    fontWeight: 'bold',
    marginBottom: 3,
    color: '#2c3e50'
  },
  companyDetails: {
    fontSize: 8,
    color: '#555',
    marginBottom: 2
  },
  title: {
    fontSize: 14,
    fontWeight: 'bold',
    textAlign: 'center',
    marginBottom: 10,
    textTransform: 'uppercase',
    color: '#2c3e50'
  },
  subtitle: {
    fontSize: 10,
    color: '#666',
    textAlign: 'center',
    marginBottom: 15
  },
  summarySection: {
    marginBottom: 15,
    padding: 12,
    backgroundColor: '#f8f9fa',
    borderRadius: 5,
    border: '1px solid #ddd'
  },
  summaryTitle: {
    fontSize: 11,
    fontWeight: 'bold',
    marginBottom: 8,
    color: '#2c3e50',
    textAlign: 'center'
  },
  summaryGrid: {
    flexDirection: 'row',
    justifyContent: 'space-between'
  },
  summaryCard: {
    width: '23%',
    padding: 8,
    backgroundColor: 'white',
    borderRadius: 4,
    textAlign: 'center',
    border: '1px solid #e0e0e0'
  },
  summaryLabel: {
    fontSize: 7,
    color: '#666',
    marginBottom: 4
  },
  summaryValue: {
    fontSize: 10,
    fontWeight: 'bold',
    color: '#2c3e50'
  },
  table: {
    display: 'table',
    width: 'auto',
    borderStyle: 'solid',
    borderWidth: 1,
    borderColor: '#bfbfbf',
    borderRightWidth: 0,
    borderBottomWidth: 0,
    marginTop: 10
  },
  tableRow: {
    margin: 'auto',
    flexDirection: 'row'
  },
  tableColHeader: {
    width: '12.5%',
    borderStyle: 'solid',
    borderWidth: 1,
    borderColor: '#bfbfbf',
    borderLeftWidth: 0,
    borderTopWidth: 0,
    backgroundColor: '#2c3e50',
    padding: 6,
    fontWeight: 'bold',
    textAlign: 'center',
    fontSize: 7,
    color: 'white'
  },
  tableCol: {
    width: '12.5%',
    borderStyle: 'solid',
    borderWidth: 1,
    borderColor: '#bfbfbf',
    borderLeftWidth: 0,
    borderTopWidth: 0,
    padding: 5,
    textAlign: 'center',
    fontSize: 6
  },
  footer: {
    position: 'absolute',
    bottom: 25,
    left: 25,
    right: 25,
    textAlign: 'center',
    fontSize: 7,
    color: '#666',
    borderTop: '1px solid #ddd',
    paddingTop: 8
  }
});

// GST PDF Component
const GSTPDF = ({ data, dateRange, summary }) => (
  <Document>
    <Page size="A4" style={gstPdfStyles.page}>
      {/* Header: Logo Left, Company Info Right */}
      <View style={gstPdfStyles.header}>
        <View style={gstPdfStyles.logoContainer}>
          <Image 
            style={gstPdfStyles.logo} 
            src="/logo.png" 
          />
          <Text style={gstPdfStyles.companyName}>E I O Digital Solutions</Text>
        </View>
        <View style={gstPdfStyles.companyInfo}>
          <Text style={gstPdfStyles.companyNameMain}>E I O Digital Solutions Private Limited</Text>
          <Text style={gstPdfStyles.companyDetails}>{companyInfo.address}</Text>
          <Text style={gstPdfStyles.companyDetails}>{companyInfo.contact}</Text>
          <Text style={gstPdfStyles.companyDetails}>{companyInfo.email}</Text>
           <Text style={gstPdfStyles.companyDetails}>{companyInfo.website}</Text>
          <Text style={gstPdfStyles.companyDetails}>{companyInfo.gstin}</Text>
        </View>
      </View>

      <Text style={gstPdfStyles.title}>
        GST REPORT
      </Text>

      <Text style={gstPdfStyles.subtitle}>
        Period: {new Date(dateRange.startDate).toLocaleDateString('en-IN')} to {new Date(dateRange.endDate).toLocaleDateString('en-IN')}
      </Text>

      {/* Summary Section */}
      <View style={gstPdfStyles.summarySection}>
        <Text style={gstPdfStyles.summaryTitle}>GST Summary</Text>
        <View style={gstPdfStyles.summaryGrid}>
          <View style={gstPdfStyles.summaryCard}>
            <Text style={gstPdfStyles.summaryLabel}>Taxable Amount</Text>
            <Text style={gstPdfStyles.summaryValue}>₹{summary.totalTaxable.toFixed(2)}</Text>
          </View>
          <View style={gstPdfStyles.summaryCard}>
            <Text style={gstPdfStyles.summaryLabel}>Total CGST</Text>
            <Text style={gstPdfStyles.summaryValue}>₹{summary.totalCGST.toFixed(2)}</Text>
          </View>
          <View style={gstPdfStyles.summaryCard}>
            <Text style={gstPdfStyles.summaryLabel}>Total SGST</Text>
            <Text style={gstPdfStyles.summaryValue}>₹{summary.totalSGST.toFixed(2)}</Text>
          </View>
          <View style={gstPdfStyles.summaryCard}>
            <Text style={gstPdfStyles.summaryLabel}>Total GST</Text>
            <Text style={gstPdfStyles.summaryValue}>₹{summary.totalGST.toFixed(2)}</Text>
          </View>
        </View>
      </View>

      {/* GST Details Table */}
      <View style={{ marginBottom: 20 }}>
        <Text style={{ fontSize: 10, fontWeight: 'bold', marginBottom: 8, color: '#2c3e50' }}>
          Invoice Details
        </Text>
        <View style={gstPdfStyles.table}>
          {/* Table Header */}
          <View style={gstPdfStyles.tableRow}>
            <Text style={gstPdfStyles.tableColHeader}>Invoice No</Text>
            <Text style={gstPdfStyles.tableColHeader}>Date</Text>
            <Text style={gstPdfStyles.tableColHeader}>Customer</Text>
            <Text style={gstPdfStyles.tableColHeader}>Taxable</Text>
            <Text style={gstPdfStyles.tableColHeader}>CGST</Text>
            <Text style={gstPdfStyles.tableColHeader}>SGST</Text>
            <Text style={gstPdfStyles.tableColHeader}>Total GST</Text>
            <Text style={gstPdfStyles.tableColHeader}>Grand Total</Text>
          </View>

          {/* Table Rows */}
          {data.map((invoice, index) => (
            <View key={invoice._id} style={gstPdfStyles.tableRow}>
              <Text style={gstPdfStyles.tableCol}>{invoice.invoiceNumber}</Text>
              <Text style={gstPdfStyles.tableCol}>
                {new Date(invoice.invoiceDate).toLocaleDateString('en-IN')}
              </Text>
              <Text style={[gstPdfStyles.tableCol, { textAlign: 'left' }]}>
                {invoice.billTo?.split('\n')[0] || 'N/A'}
              </Text>
              <Text style={gstPdfStyles.tableCol}>
                ₹{(parseFloat(invoice.taxable) || 0).toFixed(2)}
              </Text>
              <Text style={gstPdfStyles.tableCol}>
                ₹{(parseFloat(invoice.cgst) || 0).toFixed(2)}
              </Text>
              <Text style={gstPdfStyles.tableCol}>
                ₹{(parseFloat(invoice.sgst) || 0).toFixed(2)}
              </Text>
              <Text style={gstPdfStyles.tableCol}>
                ₹{((parseFloat(invoice.cgst) || 0) + (parseFloat(invoice.sgst) || 0)).toFixed(2)}
              </Text>
              <Text style={gstPdfStyles.tableCol}>
                ₹{(parseFloat(invoice.totalAmount) || 0).toFixed(2)}
              </Text>
            </View>
          ))}
        </View>
      </View>

      <Text style={gstPdfStyles.footer}>
        Generated by E I O Digital Solutions Billing System | {new Date().toLocaleDateString('en-IN')}
      </Text>
    </Page>
  </Document>
);

const GST = () => {
  const [invoices, setInvoices] = useState([]);
  const [filteredData, setFilteredData] = useState([]);
  const [dateRange, setDateRange] = useState({
    startDate: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
    endDate: new Date().toISOString().split('T')[0]
  });
  const [summary, setSummary] = useState({
    totalCGST: 0,
    totalSGST: 0,
    totalGST: 0,
    totalTaxable: 0
  });

  useEffect(() => {
    fetchInvoices();
  }, []);

  useEffect(() => {
    calculateGSTSummary();
  }, [filteredData]);

  const fetchInvoices = async () => {
    try {
      const res = await axios.get('https://billing-ki8l.onrender.com/api/invoices');
      setInvoices(res.data);
      setFilteredData(res.data);
    } catch (err) {
      console.error('Failed to fetch invoices:', err);
    }
  };

  const calculateGSTSummary = () => {
    const summaryData = filteredData.reduce((acc, invoice) => {
      acc.totalCGST += parseFloat(invoice.cgst) || 0;
      acc.totalSGST += parseFloat(invoice.sgst) || 0;
      acc.totalTaxable += parseFloat(invoice.taxable) || 0;
      return acc;
    }, { totalCGST: 0, totalSGST: 0, totalTaxable: 0 });

    summaryData.totalGST = summaryData.totalCGST + summaryData.totalSGST;
    setSummary(summaryData);
  };

  const handleDateFilter = () => {
    const filtered = invoices.filter(invoice => {
      const invoiceDate = new Date(invoice.invoiceDate);
      const start = new Date(dateRange.startDate);
      const end = new Date(dateRange.endDate);
      end.setHours(23, 59, 59, 999);
      
      return invoiceDate >= start && invoiceDate <= end;
    });
    setFilteredData(filtered);
  };

  const handleResetFilter = () => {
    setDateRange({
      startDate: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0]
    });
    setFilteredData(invoices);
  };

  const exportToExcel = () => {
    const headers = ['Invoice No', 'Date', 'Taxable Amount', 'CGST', 'SGST', 'Total GST', 'Grand Total'];
    const csvData = filteredData.map(inv => [
      inv.invoiceNumber,
      new Date(inv.invoiceDate).toLocaleDateString(),
      (parseFloat(inv.taxable) || 0).toFixed(2),
      (parseFloat(inv.cgst) || 0).toFixed(2),
      (parseFloat(inv.sgst) || 0).toFixed(2),
      ((parseFloat(inv.cgst) || 0) + (parseFloat(inv.sgst) || 0)).toFixed(2),
      (parseFloat(inv.totalAmount) || 0).toFixed(2)
    ]);

    const csvContent = [headers, ...csvData]
      .map(row => row.join(','))
      .join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `GST_Report_${dateRange.startDate}_to_${dateRange.endDate}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="gst-container">
      <div className="header-bar">
        <h2>GST Report</h2>
        <div className="header-actions">
          <PDFDownloadLink
            document={<GSTPDF data={filteredData} dateRange={dateRange} summary={summary} />}
            fileName={`GST_Report_${dateRange.startDate}_to_${dateRange.endDate}.pdf`}
            className="btn-pdf"
          >
            {({ loading }) => (loading ? 'Generating PDF...' : 'Download PDF')}
          </PDFDownloadLink>
          <button className="btn-excel" onClick={exportToExcel}>
            Export to Excel
          </button>
        </div>
      </div>

      {/* Date Filter */}
      <div className="filter-section">
        <div className="date-filter">
          <div className="filter-group">
            <label>From Date:</label>
            <input
              type="date"
              value={dateRange.startDate}
              onChange={e => setDateRange(prev => ({ ...prev, startDate: e.target.value }))}
            />
          </div>
          <div className="filter-group">
            <label>To Date:</label>
            <input
              type="date"
              value={dateRange.endDate}
              onChange={e => setDateRange(prev => ({ ...prev, endDate: e.target.value }))}
            />
          </div>
          <button className="btn-primary" onClick={handleDateFilter}>
            Apply Filter
          </button>
          <button className="btn-secondary" onClick={handleResetFilter}>
            Reset
          </button>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="summary-cards">
        <div className="summary-card taxable-card">
          <div className="card-icon">💰</div>
          <div className="card-content">
            <div className="card-header">Total Taxable Amount</div>
            <div className="card-value">₹{summary.totalTaxable.toFixed(2)}</div>
          </div>
        </div>
        <div className="summary-card cgst-card">
          <div className="card-icon">🏛️</div>
          <div className="card-content">
            <div className="card-header">Total CGST</div>
            <div className="card-value">₹{summary.totalCGST.toFixed(2)}</div>
          </div>
        </div>
        <div className="summary-card sgst-card">
          <div className="card-icon">🏛️</div>
          <div className="card-content">
            <div className="card-header">Total SGST</div>
            <div className="card-value">₹{summary.totalSGST.toFixed(2)}</div>
          </div>
        </div>
        <div className="summary-card total-gst-card">
          <div className="card-icon">📊</div>
          <div className="card-content">
            <div className="card-header">Total GST</div>
            <div className="card-value">₹{summary.totalGST.toFixed(2)}</div>
          </div>
        </div>
      </div>

      {/* GST Details Table */}
      <div className="table-container">
        <div className="table-header">
          <h3>GST Details</h3>
          <span className="record-count">{filteredData.length} records found</span>
        </div>
        <table className="data-table">
          <thead>
            <tr>
              <th>Invoice No</th>
              <th>Date</th>
              <th>Customer</th>
              <th>Taxable Amount</th>
              <th>CGST</th>
              <th>SGST</th>
              <th>Total GST</th>
              <th>Grand Total</th>
            </tr>
          </thead>
          <tbody>
            {filteredData.length === 0 ? (
              <tr>
                <td colSpan="8" className="no-data">
                  No invoices found for the selected period
                </td>
              </tr>
            ) : (
              filteredData.map(invoice => (
                <tr key={invoice._id}>
                  <td className="invoice-number">{invoice.invoiceNumber}</td>
                  <td className="invoice-date">
                    {new Date(invoice.invoiceDate).toLocaleDateString('en-IN')}
                  </td>
                  <td className="customer-name">{invoice.billTo?.split('\n')[0] || 'N/A'}</td>
                  <td className="taxable-amount">₹{(parseFloat(invoice.taxable) || 0).toFixed(2)}</td>
                  <td className="cgst-amount">₹{(parseFloat(invoice.cgst) || 0).toFixed(2)}</td>
                  <td className="sgst-amount">₹{(parseFloat(invoice.sgst) || 0).toFixed(2)}</td>
                  <td className="total-gst">
                    ₹{((parseFloat(invoice.cgst) || 0) + (parseFloat(invoice.sgst) || 0)).toFixed(2)}
                  </td>
                  <td className="grand-total">
                    <strong>₹{(parseFloat(invoice.totalAmount) || 0).toFixed(2)}</strong>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default GST;